SELECT p.id,p.code,p.name,p.status,p.category_id,c.ma brand_code,c.name brand,v.id variant_id,v.ma variant_code,s.size_value,m.ten color,cl.ten material,d.ten sole,v.price,v.quantity,v.status variant_status,l.quantity_before,l.quantity_change,l.quantity_after,l.reason,l.actor,im.duong_dan image_path FROM products p JOIN categories c ON c.id=p.category_id JOIN product_variants v ON v.product_id=p.id JOIN sizes s ON s.id=v.size_id JOIN mau_sac m ON m.id=v.mau_sac_id JOIN chat_lieu cl ON cl.id=v.chat_lieu_id JOIN de_giay d ON d.id=v.de_giay_id JOIN inventory_logs l ON l.variant_id=v.id JOIN product_images im ON im.product_id=p.id;
